query EventMarkets_Query($eventId: uuid, $marketVisibleWhere: market_bool_exp) @cached(ttl: 5) {
    event(where: { id: { _eq: $eventId } }) {
      ...MarketSelector_Frag
      ...EventData_Frag
      ...EventScoreboard_Frag
      ...CustomEvent_Frag
      id
      description
      type
      league
      scheduled_start
      status
      tournament_markets: markets {
        type
      }
      game {
        id
        awayTeam {
          id
          name
          symbol
          primary_color
          secondary_color
          swish_id
          optic_odds_id
        }
        homeTeam {
          id
          name
          symbol
          primary_color
          secondary_color
          swish_id
          optic_odds_id
        }
        end_date
        away_score
        home_score
        time_remaining
        sport
      }
    }
  }

fragment MarketData_Frag on market {
    id
    type
    strike
    status
    re_settled_at
    competitor {
      id
      name
      country
    }
    market_locks(order_by: { created_at: desc }, where: { deleted_at: { _is_null: true } }) {
      id
      market_id
      created_at
      minute_duration
    }
    player {
      id
      full_name
    }
  }

fragment Outcome_Frag on outcome {
    id
    available
    altAvailable
    index
    description
    competitor {
      id
      symbol
    }
  }

fragment StrikePriceSelector_Frag on market {
    id
    description
    eventId
    strike
    ...MarketData_Frag
    outcomes {
      id
      index
      description
      ...Outcome_Frag
    }
  }

fragment TennisScoreboard_Frag on game {
    events {
      id
      status
    }
    home_set_1
    home_set_2
    home_set_3
    home_set_4
    home_set_5
    away_set_1
    away_set_2
    away_set_3
    away_set_4
    away_set_5
    possession
    home_game_score
    away_game_score
    homeTeam {
      id
      name
    }
    awayTeam {
      id
      name
    }
  }

fragment BaseEvent_Frag on event {
    id
    status
    type
    description
    league
    scheduled_start
    event_locks(order_by: { created_at: desc }, where: { deleted_at: { _is_null: true } }) {
      id
      event_id
      minute_duration
      created_at
    }
  }

fragment MarketSelector_Frag on event {
    id
    type
    league
    markets(where: $marketVisibleWhere) {
      is_consensus
      id
      strike
      type
      description
      status
      volume
      market_detail {
        question
      }
      ...MarketData_Frag
      ...StrikePriceSelector_Frag
      outcomes {
        id
        index
        description
        available
        ...Outcome_Frag
      }
      market_locks(order_by: { created_at: desc }, where: { deleted_at: { _is_null: true } }) {
        id
        market_id
        minute_duration
        created_at
      }
      player {
        id
        full_name
        logo
        jersey_number
        player_competitors {
          competitor {
            id
            name
            short_name
            symbol
            swish_id
            optic_odds_id
            primary_color
            secondary_color
            country
          }
        }
      }
      competitor {
        id
        name
        short_name
        symbol
        swish_id
        optic_odds_id
        primary_color
        secondary_color
        country
      }
    }
    event_locks(order_by: { created_at: desc }, where: { deleted_at: { _is_null: true } }) {
      id
      event_id
      minute_duration
      created_at
    }
  }

fragment EventData_Frag on event {
    id
    type
    status
    scheduled_start
    league
    game {
      id
      league
      sport
      scheduled_start
      period
      time_remaining
      home_score
      away_score
      awayTeam {
        id
        name
        symbol
        short_name
        mascot
        primary_color
        secondary_color
        swish_id
        optic_odds_id
        wins
        losses
        draws
        country
      }
      homeTeam {
        id
        name
        symbol
        short_name
        mascot
        primary_color
        secondary_color
        swish_id
        optic_odds_id
        wins
        losses
        draws
        country
      }
    }
  }

fragment EventScoreboard_Frag on event {
    id
    type
    status
    description
    league
    scheduled_start
    game {
      id
      ...TennisScoreboard_Frag
      status
      home_score
      away_score
      period
      time_remaining
      down
      distance
      yardLine
      yardline_territory
      league
      sport
      homeTeam {
        id
        name
        short_name
        mascot
        symbol
        primary_color
        secondary_color
        wins
        losses
        draws
        swish_id
        optic_odds_id
        ranking
        country
      }
      awayTeam {
        id
        name
        short_name
        mascot
        symbol
        primary_color
        secondary_color
        wins
        losses
        draws
        swish_id
        optic_odds_id
        ranking
        country
      }
    }
    parent_event {
      id
      description
    }
    scoreboard_markets: markets(where: { type: { _eq: "MONEY" } }, limit: 1) {
      id
      type
      outcomes {
        id
        index
        status
      }
    }
    custom_markets: markets(where: { type: { _eq: "CUSTOM" } }, limit: 1) {
      id
      type
    }
  }

fragment CustomEvent_Frag on event {
    ...BaseEvent_Frag
    # Count of custom markets
    custom_event_markets_aggregate: markets_aggregate(
      where: { type: { _eq: "CUSTOM" }, status: { _eq: "OPEN" } }
    ) {
      aggregate {
        count
      }
    }
    # Total volume across custom markets
    custom_event_volume_aggregate: markets_aggregate(
      where: { type: { _eq: "CUSTOM" }, status: { _eq: "OPEN" } }
    ) {
      aggregate {
        sum {
          volume
        }
      }
    }
    # Custom markets (ordered by volume for best price sorting)
    custom_event_markets: markets(
      where: { type: { _eq: "CUSTOM" }, status: { _eq: "OPEN" } }
      order_by: { volume: desc }
    ) {
      ...MarketData_Frag
      description
      volume
      market_detail {
        question
      }
      outcomes {
        ...Outcome_Frag
      }
    }
  }
